<?php
declare(strict_types=1);
require_once __DIR__ . '/../modules/auth.php';
require_once __DIR__ . '/../modules/integrations.php';
require_once __DIR__ . '/../modules/affiliates.php';
require_login();
require_role(['owner', 'admin']);
start_app_session();

if (empty($_SESSION['integrations_csrf'])) $_SESSION['integrations_csrf'] = bin2hex(random_bytes(32));
$csrf = $_SESSION['integrations_csrf'];
$error = $flash = $oneTimeSecret = '';
$createdId = $oneTimePlatform = $oneTimeWebhookUrl = '';
$https = !empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off';
$origin = ($https ? 'https://' : 'http://') . ($_SERVER['HTTP_HOST'] ?? 'localhost');
$baseUrl = $origin . '/webhook.php';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!hash_equals($csrf, (string)($_POST['csrf'] ?? ''))) { http_response_code(403); exit('Sessão expirada. Atualize a página.'); }
    try {
        $action = (string)($_POST['action'] ?? '');
        if ($action === 'create') {
            $connection = integration_create((string)($_POST['name'] ?? ''), (string)($_POST['platform'] ?? 'kiwify'), (string)($_POST['platform_secret'] ?? $_POST['hottok'] ?? ''));
            $oneTimeSecret = (string)$connection['token'];
            $createdId = (string)$connection['id'];
            $oneTimePlatform = (string)$connection['platform'];
            if ($oneTimePlatform === 'applyfy') $oneTimeWebhookUrl = $baseUrl . '?connection=' . rawurlencode($createdId) . '&token=' . rawurlencode($oneTimeSecret);
            $flash = match ($connection['platform']) { 'hotmart' => 'Conexão Hotmart criada. O Hottok foi armazenado com segurança.', 'eduzz' => 'Conexão Eduzz criada. A chave foi armazenada com segurança.', 'applyfy' => 'Conexão Applyfy criada. A URL contém um token secreto; use o cabeçalho X-Affiliey-Webhook-Token se a plataforma permitir.', default => 'Conexão Kiwify criada. Copie o segredo agora; ele não será exibido novamente.' };
        } elseif (in_array($action, ['toggle', 'rotate'], true)) {
            $connectionId = (string)($_POST['id'] ?? '');
            if ($action === 'rotate') {
                $platformQuery = app_db()->prepare('SELECT platform FROM integration_connections WHERE id=? AND tenant_id=?');
                $platformQuery->execute([$connectionId, tenant_id()]);
                $oneTimePlatform = (string)$platformQuery->fetchColumn();
            }
            $oneTimeSecret = integration_change($connectionId, $action) ?? '';
            if ($action === 'rotate' && $oneTimePlatform === 'applyfy') $oneTimeWebhookUrl = $baseUrl . '?connection=' . rawurlencode($connectionId) . '&token=' . rawurlencode($oneTimeSecret);
            $flash = $action === 'rotate' ? 'Segredo renovado. Atualize o destino do webhook na plataforma.' : 'Status da conexão atualizado.';
        } elseif ($action === 'product_save') {
            integration_product_save((string)($_POST['connection_id'] ?? ''), (string)($_POST['external_product_id'] ?? ''), (string)($_POST['product_name'] ?? ''));
            $flash = 'Produto autorizado para esta conexão. Eventos de outros produtos serão ignorados.';
        } elseif ($action === 'product_toggle') {
            integration_product_toggle((string)($_POST['product_id'] ?? ''));
            $flash = 'Autorização do produto atualizada.';
        } elseif ($action === 'affiliate_link_save') {
            integration_affiliate_link_save((string)($_POST['connection_id'] ?? ''), (string)($_POST['affiliate_id'] ?? ''), (string)($_POST['external_affiliate_id'] ?? ''), (string)($_POST['external_email'] ?? ''));
            $flash = 'Vínculo externo do afiliado salvo para esta conexão.';
        } elseif ($action === 'affiliate_link_toggle') {
            integration_affiliate_link_toggle((string)($_POST['link_id'] ?? ''));
            $flash = 'Vínculo do afiliado atualizado.';
        } else $error = 'Ação inválida.';
    } catch (DomainException $e) { $error = $e->getMessage(); }
    catch (Throwable $e) { $error = 'Não foi possível atualizar a integração.'; }
}
$connections = integration_list();
$eligibleAffiliates = array_values(array_filter(affiliate_read_all(), static fn(array $affiliate): bool => ($affiliate['status'] ?? '') === 'active'));
$eventsStmt = app_db()->prepare('SELECT e.event_type,e.result,e.message,e.created_at,c.name AS connection_name,c.platform FROM integration_events e JOIN integration_connections c ON c.id=e.connection_id WHERE e.tenant_id=? ORDER BY e.created_at DESC LIMIT 30');
$eventsStmt->execute([tenant_id()]); $events = $eventsStmt->fetchAll();
function ine($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
?>
