    <form method="post" class="scope-form product-form"><input type="hidden" name="csrf" value="<?= ine($csrf) ?>"><input type="hidden" name="action" value="product_save"><input type="hidden" name="connection_id" value="<?= ine($connection['id']) ?>"><label>ID oficial do produto<input name="external_product_id" maxlength="120" required placeholder="ID informado pela plataforma"></label><label>Nome do produto<input name="product_name" maxlength="160" required placeholder="Nome para identificar"></label><button class="button primary" type="submit">Autorizar produto</button></form>
    <?php if ($products): ?><ul class="scope-list"><?php foreach ($products as $product): ?><li><span><b><?= ine($product['name']) ?></b><small>ID <?= ine($product['external_product_id']) ?> · <?= $product['status'] === 'active' ? 'Sincronizando' : 'Pausado' ?></small></span><form method="post"><input type="hidden" name="csrf" value="<?= ine($csrf) ?>"><input type="hidden" name="action" value="product_toggle"><input type="hidden" name="product_id" value="<?= ine($product['id']) ?>"><button class="text-button" type="submit"><?= $product['status'] === 'active' ? 'Desautorizar' : 'Reativar' ?></button></form></li><?php endforeach; ?></ul><?php else: ?><p class="scope-empty">Cadastre pelo menos um produto autorizado para começar a receber vendas.</p><?php endif; ?>
